@asynccontextmanager
async def lifespan(app: FastAPI):
    global _ai_client, _http_client, _db_pool, _obj_client
    missing = [k for k, v in [("FRIENDLI_TOKEN", _FRIENDLI_TOKEN), ("EXA_API_KEY", _EXA_API_KEY)] if not v]
