        logger.warning("Missing required environment variables: %s", ", ".join(missing))
    for path in ("index.html", "static/sw.js"):
        if not os.path.isfile(path):
            logger.error("Required file not found at startup: %s", path)
    if not os.path.isdir("static"):
        logger.error("static/ directory not found at startup")
    _ai_client = AsyncOpenAI(
        api_key=_FRIENDLI_TOKEN or "missing",
        base_url="",
    )
    _http_client = httpx.AsyncClient(
        timeout=60.0,
        limits=httpx.Limits(max_connections=20, max_keepalive_connections=10),
    )
    try:
        _db_pool = await asyncpg.create_pool(DB_URL, min_size=2, max_size=10, statement_cache_size=0)
        await _db_pool.execute("""
            CREATE TABLE IF NOT EXISTS sessions (
                id TEXT PRIMARY KEY,
                messages JSONB NOT NULL DEFAULT '[]',
                created_at DOUBLE PRECISION NOT NULL,
                updated_at DOUBLE PRECISION NOT NULL
            );
            CREATE INDEX IF NOT EXISTS sessions_updated ON sessions(updated_at DESC);
        """)
        logger.info("Database pool created")
    except Exception as exc:
        logger.error("Failed to create database pool: %s", exc)
        _db_pool = None
    try:
        _obj_client = ObjClient(OBJ_BUCKET)
        logger.info("Object storage client created")
    except Exception as exc:
        logger.error("Failed to create object storage client: %s", exc)
        _obj_client = None
    logger.info("Application started")
    yield
    if _http_client:
        await _http_client.aclose()
    if _db_pool:
        await _db_pool.close()
    logger.info("Application stopped")


