async def _messages_for_db(sid: str, messages: list) -> list:
    loop = asyncio.get_event_loop()
    db_messages = []
    for m in messages:
        if isinstance(m.get("content"), list):
            db_parts = []
            for part in m["content"]:
                if part.get("type") == "image_url":
                    url = part["image_url"]["url"]
                    if url.startswith("data:") and _obj_client:
                        try:
                            header, b64_data = url.split(";base64,", 1)
                            media_type = header.split(":", 1)[1]
                            img_bytes = base64.b64decode(b64_data)
                            key = f"images/{sid}/{uuid.uuid4().hex}"
                            await loop.run_in_executor(None, _upload_image_sync, key, img_bytes, media_type)
                            db_parts.append({"type": "image_ref", "key": key, "media_type": media_type})
                        except Exception as exc:
                            logger.warning("Failed to upload image to object store: %s", exc)
                            db_parts.append({"type": "text", "text": "[kép]"})
                    else:
                        db_parts.append(part)
                else:
                    db_parts.append(part)
            db_messages.append({**m, "content": db_parts})
        else:
            db_messages.append(m)
    return db_messages


async def save_session_to_db(sid: str, messages: list) -> None:
    if not _db_pool:
        return
    try:
        db_msgs = await _messages_for_db(sid, messages)
        now = time.time()
        await _db_pool.execute(
            """
            INSERT INTO sessions (id, messages, created_at, updated_at)
            VALUES ($1, $2::jsonb, $3, $3)
            ON CONFLICT (id) DO UPDATE SET messages = $2::jsonb, updated_at = $3
            """,
            sid, json.dumps(db_msgs), now,
        )
    except Exception as exc:
        logger.error("Failed to save session %s to DB: %s", sid, exc)


def _msgs_db_to_readable(msgs: list) -> list:
    readable = []
    for m in msgs:
        role = m.get("role")
        if role not in ("user", "assistant"):
            continue
        if role == "assistant" and m.get("tool_calls") and not m.get("content"):
            continue
        content = m.get("content")
        if isinstance(content, list):
            text = next((p.get("text", "") for p in content if p.get("type") == "text"), "")
            images = [p for p in content if p.get("type") in ("image_url", "image_ref")]
            has_image = bool(images)
            image_keys = [p["key"] for p in images if p.get("type") == "image_ref"]
            readable.append({
                "role": role,
                "content": text,
                "has_image": has_image,
                "image_keys": image_keys,
            })
        elif isinstance(content, str) and content:
            readable.append({"role": role, "content": content, "has_image": False, "image_keys": []})
    return readable


async def call_exa(params: dict) -> dict:
    if not _EXA_API_KEY:
        raise RuntimeError("EXA_API_KEY is not configured")
    query = params.get("query", "")
    if not query:
        raise ValueError("Search query is required")
    payload: dict = {
        "query": query,
        "numResults": 100,
        "contents": {
            "summary": {"query": params.get("summaryQuery") or query}
        },
    }
    if params.get("maxAgeHours") is not None:
        payload["contents"]["maxAgeHours"] = int(params["maxAgeHours"])
    search_type = params.get("type") or "auto"
    payload["type"] = search_type
    for field in ["category", "startPublishedDate", "endPublishedDate",
                  "includeDomains", "excludeDomains", "userLocation"]:
        val = params.get(field)
        if val is not None and val != "" and val != []:
            payload[field] = val
    if search_type in DEEP_SEARCH_TYPES:
        for field in ["additionalQueries", "systemPrompt"]:
            val = params.get(field)
            if val is not None and val != "" and val != []:
                payload[field] = val
    last_exc: Exception = RuntimeError("Exa call failed")
    for attempt in range(3):
        try:
            r = await _http_client.post(
                "",
                headers={"x-api-key": _EXA_API_KEY, "Content-Type": "application/json"},
                json=payload,
            )
            r.raise_for_status()
            return r.json()
        except (httpx.TransportError, httpx.TimeoutException) as exc:
            last_exc = exc
            if attempt < 2:
                await asyncio.sleep(1.5 ** attempt)
        except httpx.HTTPStatusError as exc:
            last_exc = exc
            if exc.response.status_code in (429, 500, 502, 503) and attempt < 2:
                await asyncio.sleep(1.5 ** attempt)
                continue
            raise
    raise last_exc


def format_exa_for_sse(exa_result: dict) -> tuple[list, int]:
    results = exa_result.get("results", [])
    total = len(results)
    out = []
    for r in results[:20]:
        raw = r.get("summary")
        summary = ""
        if isinstance(raw, dict):
            summary = raw.get("text", "")[:400]
        elif isinstance(raw, str):
            summary = raw[:400]
        out.append({
            "title": (r.get("title") or "")[:120],
            "url": r.get("url", ""),
            "summary": summary,
            "published_date": r.get("publishedDate", ""),
        })
    return out, total


def format_exa_for_model(exa_result: dict, query: str) -> str:
    results = exa_result.get("results", [])
    seen_urls: set[str] = set()
    lines = [f'Web search results for: "{query}"', ""]
    count = 0
    for r in results:
        url = r.get("url", "")
        if url in seen_urls:
            continue
        seen_urls.add(url)
        count += 1
        title = (r.get("title") or "")[:120]
        published = r.get("publishedDate", "")
        raw = r.get("summary")
        summary = ""
        if isinstance(raw, dict):
            summary = raw.get("text", "")[:MAX_SUMMARY_CHARS]
        elif isinstance(raw, str):
            summary = raw[:MAX_SUMMARY_CHARS]
        lines.append(f"[{count}] {title}")
        lines.append(f"    URL: {url}")
        if published:
            lines.append(f"    Published: {published}")
        if summary:
            lines.append(f"    Summary: {summary}")
        lines.append("")
    return "\n".join(lines)


