    except Exception as exc:
        logger.error("Failed to fetch image %s: %s", key, exc)
        raise HTTPException(status_code=404, detail="Image not found")


@app.post("/api/chat")
async def chat_endpoint(req: ChatRequest):
    sid, history = await get_or_create_session(req.session_id)

    if req.images:
        content_parts: list = [{"type": "text", "text": req.message}]
        for img in req.images:
            try:
                b64 = strip_b64_prefix(img.data)
            except ValueError as exc:
                logger.warning("Skipping invalid image: %s", exc)
                continue
            content_parts.append({
                "type": "image_url",
                "image_url": {"url": f"data:{img.media_type};base64,{b64}", "detail": "high"},
            })
        user_msg: dict = {"role": "user", "content": content_parts}
    else:
        user_msg = {"role": "user", "content": req.message}

    entry_len = len(history)
    history.append(user_msg)

    async def generate():
        yield f"data: {json.dumps({'type': 'session', 'session_id': sid})}\n\n"

        reasoning_started = False
        reasoning_done = False

        try:
            iteration = 0
            while iteration < MAX_TOOL_ITERATIONS:
                iteration += 1
                reasoning_started = False
                reasoning_done = False

                stream = await _ai_client.chat.completions.create(
                    model="zai-org/GLM-5",
                    max_tokens=200000,
                    temperature=1,
                    top_p=0.95,
                    extra_body={
                        "parse_reasoning": True,
                        "chat_template_kwargs": {"enable_thinking": True},
                    },
                    tools=[EXA_TOOL, IMAGE_TOOL],
                    tool_choice="auto",
                    messages=[{"role": "system", "content": SYSTEM_PROMPT}] + build_api_messages(history),
                    stream=True,
                )

                tool_call_chunks: dict[int, dict] = {}
                finish_reason: str | None = None
                turn_content = ""

                async for chunk in stream:
                    if not chunk.choices:
                        continue
                    choice = chunk.choices[0]
                    delta = choice.delta
                    if choice.finish_reason:
                        finish_reason = choice.finish_reason

                    reasoning = getattr(delta, "reasoning_content", None)
                    content = getattr(delta, "content", None)

                    if reasoning:
                        if not reasoning_started:
                            reasoning_started = True
