        img_bytes = base64.b64decode(b64_str)
        obj_key = f"generated/{sid}/{uuid.uuid4().hex}.jpg"
        if _obj_client:
            try:
                await loop.run_in_executor(None, _upload_image_sync, obj_key, img_bytes, "image/jpeg")
            except Exception as exc:
                logger.warning("Failed to upload generated image to object store: %s", exc)
                obj_key = ""
        events.append(json.dumps({
            "type": "image_generated",
            "id": tc_id,
            "prompt": prompt,
            "image": b64_str,
            "key": obj_key,
        }))
        tool_msg = {"role": "tool", "tool_call_id": tc_id, "content": f"Image generated successfully for prompt: \"{prompt}\". The image has been displayed to the user."}
    except FlyMyAIPredictException as exc:
        logger.error("FlyMyAI generation failed: %s", exc)
        events.append(json.dumps({"type": "image_error", "id": tc_id, "error": str(exc)}))
        tool_msg = {"role": "tool", "tool_call_id": tc_id, "content": f"Image generation failed: {exc}"}
    except Exception as exc:
        logger.error("Image generation error: %s", exc)
        events.append(json.dumps({"type": "image_error", "id": tc_id, "error": str(exc)}))
        tool_msg = {"role": "tool", "tool_call_id": tc_id, "content": f"Image generation failed: {exc}"}
    return events, tool_msg


async def execute_tool(tc_data: dict, sid: str = "") -> tuple[list[str], dict]:
    name = tc_data.get("name", "")
    if name == "generate_image":
        return await execute_image_tool(tc_data, sid)

    tc_id = tc_data.get("id") or f"tc_{uuid.uuid4().hex[:8]}"
    args_str = (tc_data.get("arguments") or "").strip()
    try:
        params = json.loads(args_str) if args_str else {}
    except Exception:
        params = {}
    query = params.get("query", "")
    if not query:
        ev = json.dumps({"type": "search_error", "query": "", "id": tc_id, "error": "Empty query"})
        return [ev], {"role": "tool", "tool_call_id": tc_id, "content": "Search failed: empty query"}
    events: list[str] = []
    events.append(json.dumps({"type": "search_start", "query": query, "id": tc_id}))
    try:
        exa_result = await call_exa(params)
        sse_results, total = format_exa_for_sse(exa_result)
        events.append(json.dumps({"type": "search_results", "query": query, "id": tc_id, "results": sse_results, "total": total}))
        model_content = format_exa_for_model(exa_result, query)
    except Exception as exc:
        logger.error("Exa search failed for query %r: %s", query, exc)
        events.append(json.dumps({"type": "search_error", "query": query, "id": tc_id, "error": str(exc)}))
        model_content = f"Search for '{query}' failed: {exc}"
    return events, {"role": "tool", "tool_call_id": tc_id, "content": model_content}


