@app.post("/api/chat")
async def chat_endpoint(req: ChatRequest):
    sid, history = await get_or_create_session(req.session_id)

    if req.images:
        content_parts: list = [{"type": "text", "text": req.message}]
        for img in req.images:
            try:
                b64 = strip_b64_prefix(img.data)
            except ValueError as exc:
                logger.warning("Skipping invalid image: %s", exc)
                continue
            content_parts.append({
                "type": "image_url",
                "image_url": {"url": f"data:{img.media_type};base64,{b64}", "detail": "high"},
            })
        user_msg: dict = {"role": "user", "content": content_parts}
    else:
        user_msg = {"role": "user", "content": req.message}

    entry_len = len(history)
    history.append(user_msg)

    async def generate():
        yield f"data: {json.dumps({'type': 'session', 'session_id': sid})}\n\n"

        reasoning_started = False
        reasoning_done = False

        try:
            iteration = 0
            while iteration < MAX_TOOL_ITERATIONS:
                iteration += 1
                reasoning_started = False
                reasoning_done = False

                stream = await _ai_client.chat.completions.create(
                    model="zai-org/GLM-5",
                    max_tokens=200000,
                    temperature=1,
                    top_p=0.95,
                    extra_body={
                        "parse_reasoning": True,
                        "chat_template_kwargs": {"enable_thinking": True},
                    },
                    tools=[EXA_TOOL, IMAGE_TOOL],
                    tool_choice="auto",
                    messages=[{"role": "system", "content": SYSTEM_PROMPT}] + build_api_messages(history),
                    stream=True,
                )

                tool_call_chunks: dict[int, dict] = {}
                finish_reason: str | None = None
                turn_content = ""

                async for chunk in stream:
                    if not chunk.choices:
                        continue
                    choice = chunk.choices[0]
                    delta = choice.delta
                    if choice.finish_reason:
                        finish_reason = choice.finish_reason

                    reasoning = getattr(delta, "reasoning_content", None)
                    content = getattr(delta, "content", None)

                    if reasoning:
                        if not reasoning_started:
                            reasoning_started = True
                            yield f"data: {json.dumps({'type': 'reasoning_start'})}\n\n"
                        yield f"data: {json.dumps({'type': 'reasoning', 'text': reasoning})}\n\n"

                    if content:
                        if reasoning_started and not reasoning_done:
                            reasoning_done = True
                            yield f"data: {json.dumps({'type': 'reasoning_end'})}\n\n"
                        turn_content += content
                        yield f"data: {json.dumps({'type': 'content', 'text': content})}\n\n"

                    if delta.tool_calls:
                        for tc in delta.tool_calls:
                            idx = tc.index
                            if idx is None:
                                continue
                            if idx not in tool_call_chunks:
                                tool_call_chunks[idx] = {"id": "", "name": "", "arguments": ""}
                            if tc.id:
                                tool_call_chunks[idx]["id"] = tc.id
                            if tc.function:
                                if tc.function.name:
                                    tool_call_chunks[idx]["name"] = tc.function.name
                                if tc.function.arguments:
                                    tool_call_chunks[idx]["arguments"] += tc.function.arguments

                if finish_reason == "tool_calls" and tool_call_chunks:
                    valid_indices = sorted(k for k in tool_call_chunks if k is not None)
                    tool_calls_list = [
                        {
                            "id": tool_call_chunks[idx].get("id") or f"tc_{idx}",
                            "type": "function",
                            "function": {
                                "name": tool_call_chunks[idx]["name"],
                                "arguments": tool_call_chunks[idx]["arguments"],
                            },
                        }
                        for idx in valid_indices
                    ]
                    history.append({
                        "role": "assistant",
                        "content": turn_content or "",
                        "tool_calls": tool_calls_list,
                    })
                    async with sessions_lock:
                        if sid in sessions:
                            sessions[sid]["updated_at"] = time.time()

                    tool_tasks = [execute_tool(tool_call_chunks[idx], sid) for idx in valid_indices]
                    tool_results = await asyncio.gather(*tool_tasks)

                    for events_list, tool_msg in tool_results:
                        for ev_data in events_list:
                            yield f"data: {ev_data}\n\n"
                        history.append(tool_msg)

                    yield f"data: {json.dumps({'type': 'search_done'})}\n\n"

                else:
                    history.append({"role": "assistant", "content": turn_content})
                    async with sessions_lock:
                        if sid in sessions:
                            sessions[sid]["updated_at"] = time.time()
                    asyncio.create_task(save_session_to_db(sid, list(history)))
                    yield f"data: {json.dumps({'type': 'done', 'session_id': sid})}\n\n"
                    break

        except Exception as exc:
            logger.error("Generate error for session %s: %s", sid, exc)
            del history[entry_len:]
            yield f"data: {json.dumps({'type': 'error', 'message': str(exc)})}\n\n"

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


