    return {"cleared": True}


@app.get("/api/sessions")
async def list_sessions():
    result = []
    if _db_pool:
        try:
            rows = await _db_pool.fetch(
                "SELECT id, messages FROM sessions ORDER BY updated_at DESC LIMIT 100"
            )
            for row in rows:
                msgs = json.loads(row["messages"])
                user_msgs = [m for m in msgs if m.get("role") == "user"]
                if not user_msgs:
                    continue
                first = user_msgs[0]
                content = first.get("content")
                if isinstance(content, list):
                    preview = next((p.get("text", "") for p in content if p.get("type") == "text"), "")
                elif isinstance(content, str):
                    preview = content
                else:
                    preview = ""
                total = len([
                    m for m in msgs
                    if m.get("role") in ("user", "assistant")
                    and not (m.get("role") == "assistant" and m.get("tool_calls") and not m.get("content"))
                ])
                result.append({"session_id": row["id"], "preview": preview[:80], "count": total})
        except Exception as exc:
            logger.error("Failed to list sessions from DB: %s", exc)
    else:
        async with sessions_lock:
            snapshot = {k: {"messages": list(v["messages"])} for k, v in sessions.items()}
        for sid, sess in snapshot.items():
            msgs = sess["messages"]
            user_msgs = [m for m in msgs if m.get("role") == "user"]
            if not user_msgs:
                continue
            first = user_msgs[0]
            content = first.get("content")
            if isinstance(content, list):
                preview = next((p.get("text", "") for p in content if p.get("type") == "text"), "")
            elif isinstance(content, str):
                preview = content
            else:
                preview = ""
            total = len([
                m for m in msgs
                if m.get("role") in ("user", "assistant")
                and not (m.get("role") == "assistant" and m.get("tool_calls") and not m.get("content"))
            ])
            result.append({"session_id": sid, "preview": preview[:80], "count": total})
    return {"sessions": result}


